-- UniFlow's database, authorization, notification, and storage foundation.
create extension if not exists pgcrypto;
create type public.app_role as enum ('student','admin','staff');
create type public.complaint_status as enum ('submitted','acknowledged','in_progress','resolved','reopened');
create type public.complaint_priority as enum ('low','medium','high','urgent');
create table public.profiles(id uuid primary key references auth.users on delete cascade, full_name text not null check(char_length(full_name) between 2 and 120), role public.app_role not null default 'student', room_number text, created_at timestamptz not null default now());
create table public.staff(id uuid primary key references public.profiles(id) on delete cascade, department text not null, active boolean not null default true);
create table public.complaints(id uuid primary key default gen_random_uuid(), ticket_number text unique not null default ('UF-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))), student_id uuid not null references public.profiles(id), assigned_staff_id uuid references public.profiles(id), title text not null check(char_length(title) between 3 and 120), category text not null, description text not null check(char_length(description) between 10 and 2000), room_number text not null, priority public.complaint_priority not null default 'medium', status public.complaint_status not null default 'submitted', resolution_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.complaint_history(id uuid primary key default gen_random_uuid(), complaint_id uuid not null references public.complaints on delete cascade, actor_id uuid references public.profiles(id), old_status public.complaint_status, new_status public.complaint_status, note text, created_at timestamptz not null default now());
create table public.complaint_images(id uuid primary key default gen_random_uuid(), complaint_id uuid not null references public.complaints on delete cascade, storage_path text unique not null, created_at timestamptz not null default now());
create table public.food_menus(id uuid primary key default gen_random_uuid(), menu_date date unique not null, breakfast text not null, lunch text not null, snacks text not null, dinner text not null, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table public.food_feedback(id uuid primary key default gen_random_uuid(), student_id uuid not null default auth.uid() references public.profiles(id), rating int not null check(rating between 1 and 5), category text not null, comment text not null check(char_length(comment) between 3 and 1000), created_at timestamptz not null default now());
create table public.notices(id uuid primary key default gen_random_uuid(), title text not null, body text not null, category text not null default 'general', priority text not null default 'normal', published_at timestamptz not null default now(), expires_at timestamptz, created_by uuid references public.profiles(id));
create table public.knowledge_articles(id uuid primary key default gen_random_uuid(), title text not null, category text not null, body text not null, source_name text, source_url text, verified boolean not null default false, published boolean not null default false, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(), recipient_id uuid not null references public.profiles(id) on delete cascade, title text not null, body text not null, link text, read_at timestamptz, created_at timestamptz not null default now());
create table public.ai_conversations(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, role text not null check(role in ('user','assistant')), content text not null check(char_length(content)<=8000), created_at timestamptz not null default now());
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='admin')$$;
create function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='staff')$$;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name,room_number) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','Student'),nullif(new.raw_user_meta_data->>'room_number','')); return new; end;$$;
create trigger new_user_profile after insert on auth.users for each row execute procedure public.handle_new_user();
create function public.log_complaint_update() returns trigger language plpgsql security definer set search_path=public as $$begin if tg_op='INSERT' then insert into complaint_history(complaint_id,actor_id,new_status,note) values(new.id,auth.uid(),new.status,'Complaint submitted'); insert into notifications(recipient_id,title,body,link) values(new.student_id,'Complaint submitted','Your ticket '||new.ticket_number||' was created.','/complaints'); elsif new.status is distinct from old.status or new.resolution_notes is distinct from old.resolution_notes then insert into complaint_history(complaint_id,actor_id,old_status,new_status,note) values(new.id,auth.uid(),old.status,new.status,new.resolution_notes); insert into notifications(recipient_id,title,body,link) values(new.student_id,'Complaint updated','Your ticket '||new.ticket_number||' is now '||replace(new.status::text,'_',' ')||'.','/complaints'); end if; new.updated_at=now(); return new;end;$$;
create trigger complaint_history_trigger before insert or update on public.complaints for each row execute procedure public.log_complaint_update();
alter table public.profiles enable row level security; alter table public.staff enable row level security; alter table public.complaints enable row level security; alter table public.complaint_history enable row level security; alter table public.complaint_images enable row level security; alter table public.food_menus enable row level security; alter table public.food_feedback enable row level security; alter table public.notices enable row level security; alter table public.knowledge_articles enable row level security; alter table public.notifications enable row level security; alter table public.ai_conversations enable row level security;
create policy "profiles own read" on profiles for select using(id=auth.uid() or public.is_admin()); create policy "profiles admin update" on profiles for update using(public.is_admin());
create policy "complaints select scoped" on complaints for select using(student_id=auth.uid() or assigned_staff_id=auth.uid() or public.is_admin()); create policy "students create tickets" on complaints for insert with check(student_id=auth.uid() and exists(select 1 from profiles where id=auth.uid() and role='student')); create policy "staff admin update scoped" on complaints for update using(public.is_admin() or assigned_staff_id=auth.uid()) with check(public.is_admin() or assigned_staff_id=auth.uid());
create policy "history scoped" on complaint_history for select using(exists(select 1 from complaints c where c.id=complaint_id and (c.student_id=auth.uid() or c.assigned_staff_id=auth.uid() or public.is_admin())));
create policy "menus readable" on food_menus for select to authenticated using(true); create policy "menus admin write" on food_menus for all using(public.is_admin()) with check(public.is_admin());
create policy "feedback own or admin read" on food_feedback for select using(student_id=auth.uid() or public.is_admin()); create policy "students add own feedback" on food_feedback for insert with check(student_id=auth.uid());
create policy "active notices readable" on notices for select to authenticated using(published_at<=now() and (expires_at is null or expires_at>now()) or public.is_admin()); create policy "notices admin write" on notices for all using(public.is_admin()) with check(public.is_admin());
create policy "verified articles read" on knowledge_articles for select to authenticated using((verified and published) or public.is_admin()); create policy "articles admin write" on knowledge_articles for all using(public.is_admin()) with check(public.is_admin());
create policy "notifications own" on notifications for select using(recipient_id=auth.uid()); create policy "conversation own" on ai_conversations for select using(user_id=auth.uid());
alter publication supabase_realtime add table public.complaints, public.notifications, public.notices;
insert into storage.buckets(id,name,public) values('complaint-images','complaint-images',false) on conflict do nothing;
create policy "own complaint images upload" on storage.objects for insert to authenticated with check(bucket_id='complaint-images' and (storage.foldername(name))[1]=auth.uid()::text); create policy "scoped complaint images read" on storage.objects for select to authenticated using(bucket_id='complaint-images' and (storage.foldername(name))[1]=auth.uid()::text);
-- Promote the first hostel administrator manually after signup, e.g.:
-- update public.profiles set role='admin' where id='USER_UUID';
